from .money import _MAX_CENTS, _amount_to_cents, _cents_to_decimal, format_amount


def make_invoice(amounts):
    """Build an invoice total from a list of monetary amounts.

    Every item is validated exactly like :func:`src.money.parse_amount`.
    Amounts are summed as integer cents, so the result is exact even when
    the caller's decimal context precision is too low for the values.
    """
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")

    total_cents = 0
    for amount in amounts:
        total_cents += _amount_to_cents(amount)

    if total_cents > _MAX_CENTS:
        raise ValueError("invoice total must not exceed 1000000.00")

    return {
        "total": format_amount(_cents_to_decimal(total_cents)),
        "count": len(amounts),
    }

