"""Exact monetary amount parsing and formatting.

Amounts are validated and converted to integer cents before any arithmetic
is performed, so results never depend on (or mutate) the caller's current
decimal context.  Decimal results are constructed directly from their digit
tuple, which is exact regardless of context precision.
"""

import re
from decimal import Decimal

# Full grammar for string inputs: ASCII digits only, optional sign, digits
# required on both sides of the decimal point when one is present.
_AMOUNT_PATTERN = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")

_MAX_WHOLE = 1000000             # largest allowed whole amount
_MAX_CENTS = 100000000           # 1000000.00 expressed in cents
_MAX_DECIMAL = Decimal("1000000.00")


def _cents_from_string(text):
    """Convert a strictly validated decimal string to integer cents."""
    if _AMOUNT_PATTERN.fullmatch(text) is None:
        raise ValueError("amount string does not match [+-]?[0-9]+(?:[.][0-9]+)?")

    negative = False
    if text[0] in "+-":
        negative = text[0] == "-"
        text = text[1:]

    if "." in text:
        whole, fraction = text.split(".", 1)
    else:
        whole, fraction = text, ""

    whole = whole.lstrip("0") or "0"
    # Guard the int() conversion against absurdly long (but valid) strings.
    if len(whole) > 7:
        raise ValueError("amount must not exceed 1000000.00")
    whole_value = int(whole)

    if len(fraction) > 2 and any(char != "0" for char in fraction[2:]):
        raise ValueError("amount is not exactly representable in cents")

    cents = whole_value * 100 + int((fraction + "00")[:2])

    if negative:
        raise ValueError("amount must be positive")
    if cents <= 0 or cents > _MAX_CENTS:
        raise ValueError("amount must be positive and not exceed 1000000.00")
    return cents


def _cents_from_int(value):
    """Convert a validated non-bool integer to integer cents."""
    if value <= 0 or value > _MAX_WHOLE:
        raise ValueError("amount must be positive and not exceed 1000000")
    return value * 100


def _cents_from_decimal(value):
    """Convert a validated Decimal to integer cents, exactly."""
    if not value.is_finite():
        raise ValueError("amount must be finite")
    if value <= 0 or value > _MAX_DECIMAL:
        raise ValueError("amount must be positive and not exceed 1000000.00")
    # Any positive value below 0.01 cannot be a whole number of cents.
    if value.adjusted() < -2:
        raise ValueError("amount is not exactly representable in cents")

    numerator, denominator = value.as_integer_ratio()
    scaled = numerator * 100
    if scaled % denominator != 0:
        raise ValueError("amount is not exactly representable in cents")
    cents = scaled // denominator
    if cents > _MAX_CENTS:
        raise ValueError("amount must not exceed 1000000.00")
    return cents


def _amount_to_cents(value):
    """Validate ``value`` and return the exact equivalent number of cents."""
    if isinstance(value, bool):
        raise ValueError("boolean is not a valid amount")
    if isinstance(value, Decimal):
        return _cents_from_decimal(value)
    if isinstance(value, int):
        return _cents_from_int(value)
    if isinstance(value, str):
        return _cents_from_string(value)
    raise ValueError("amount must be a Decimal, int, or str")


def _cents_to_decimal(cents):
    """Build a Decimal with exponent -2 from integer cents, exactly."""
    sign = 0
    if cents < 0:
        sign, cents = 1, -cents
    digits = tuple(int(char) for char in str(cents))
    return Decimal((sign, digits, -2))


def parse_amount(value):
    """Parse a monetary amount into a Decimal quantized to cents.

    Accepts Decimal objects, ints (excluding bool), and strings matching
    ``[+-]?[0-9]+(?:\\.[0-9]+)?``.  Rejects non-finite values, zero,
    negatives, values above 1000000.00, and values that are not exactly
    representable in cents.  The returned Decimal always has exponent -2.
    """
    return _cents_to_decimal(_amount_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
